"""Progressive setup presentation around the existing authoritative save handler."""
import html,json

def staged(html_page,values,prefix,csrf,servers):
    e=lambda x:html.escape(str(x),quote=True)
    def check(name,en,fa):return f'<label class="setup-module"><input type="checkbox" name="feature_{name}" value="1" {"checked" if values.get("feature_"+name)=="1" else ""}><span data-en="{en}" data-fa="{fa}">{en}</span></label>'
    modules='<section class="step"><h2 data-en="2) Modules" data-fa="۲) قابلیت‌ها">2) Modules</h2><div class="grid">'+''.join(check(*row) for row in [('resellers','Reseller sales','فروش نمایندگی'),('openvpn','OpenVPN tools','ابزارهای OpenVPN'),('trials','Trial accounts','اکانت تست'),('wallet','Wallet','کیف پول'),('tutorials','Tutorials','آموزش‌ها'),('xray','Xray for Telegram connection (optional download)','Xray برای اتصال تلگرام (دانلود اختیاری)')])+'</div><p data-en="External VPN panels are connected; this step does not install them on this VPS." data-fa="پنل‌های VPN خارجی متصل می‌شوند؛ این مرحله آن‌ها را روی این VPS نصب نمی‌کند.">External VPN panels are connected; this step does not install them on this VPS.</p></section>'
    rows=''.join(f'<li data-provider="{e(s.server_type)}">{e(s.name)}</li>' for s in servers)
    server='<section class="step"><h2 data-en="1) Servers" data-fa="۱) سرورها">1) Servers</h2><ul id="setupServers" hidden>'+rows+'</ul><div id="setupServerForm" class="grid">'
    server+='<label><span data-en="Panel type" data-fa="نوع پنل">Panel type</span><select data-server="server_type"><option value="xui">Sanaei / 3x-ui</option><option value="pasarguard">PasarGuard</option><option value="nx">NX Panel</option><option value="mikrotik">MikroTik</option></select></label>'
    for key,en,fa,typ in [('name','Server name','نام سرور','text'),('panel_url','Panel URL','آدرس پنل','url'),('panel_path','Panel path','مسیر پنل','text'),('username','Panel username','نام کاربری پنل','text'),('password','Panel password','رمز عبور پنل','password'),('api_key','API token','توکن API','password')]:
        server+=f'<label><span data-en="{en}" data-fa="{fa}">{en}</span><input data-server="{key}" type="{typ}" value="{"/" if key=="panel_path" else ""}" autocomplete="off"></label>'
    server+='<label><span data-en="Sales channels" data-fa="کاربرد سرور">Sales channels</span><select data-server="scope"><option value="public" data-en="Public" data-fa="عمومی">Public</option><option value="reseller" data-en="Reseller" data-fa="نمایندگی">Reseller</option><option value="all" data-en="Public + Reseller" data-fa="عمومی و نمایندگی">Public + Reseller</option></select></label><div class="full"><button type="button" class="btn primary" id="setupAddServer" data-en="Verify and save server" data-fa="بررسی اتصال و ذخیره سرور">Verify and save server</button></div><p id="setupServerSuccess" class="full" role="status" aria-live="polite" hidden></p></div></section>'
    from app.services.setup_restore import markup,script as restore_script
    server=server.replace('</div></section>','</div>'+markup()+'</section>',1)
    extras=''
    for key,en,fa,feature in [('servers','Server and reseller roles','سرورها و نقش نمایندگی',''),('service-types','Service types','انواع سرویس',''),('categories','Categories','دسته‌بندی‌ها',''),('plans','Plans and pricing','پلن‌ها و قیمت‌گذاری',''),('payments','Payment methods','روش‌های پرداخت',''),('resellers','Reseller options','تنظیمات نمایندگی','resellers'),('pasarguard-panel-sales','Panel sales','فروش پنل نمایندگی','resellers'),('test-account','Trial accounts','اکانت تست','trials'),('openvpn-profiles','OpenVPN profiles','پروفایل‌های OpenVPN','openvpn'),('settings','Bot, Mini App and tutorials','ربات، مینی‌اپ و آموزش‌ها',''),('miniapp','Mini App','مینی‌اپ',''),('discounts','Discounts','تخفیف‌ها',''),('custom','Buttons and messages','دکمه‌ها و پیام‌ها',''),('connection','Telegram connection','اتصال تلگرام',''),('backup','Backup','پشتیبان‌گیری','')]:
        extras+=f'<section class="step" data-feature="{feature}"><h2 data-en="{en}" data-fa="{fa}">{en}</h2><p data-en="Save changes using the form before continuing." data-fa="تغییرات را با دکمه ذخیره همین فرم ثبت کنید، سپس ادامه دهید.">Save changes using the form before continuing.</p><iframe title="{en}" data-src="{e(prefix)}/setup/options/{key}" loading="lazy"></iframe></section>'
    html_page=html_page.replace('<div class="steps">','<div class="steps">'+server+modules,1)
    html_page=html_page.replace('</div><div class="actions">',extras+'</div><div class="actions">',1)
    for button_class in ('btn', 'btn primary'):
        html_page=html_page.replace('<div class="actions"><button class="'+button_class+'" type="submit">','<div id="setupError" role="alert" aria-live="assertive"></div><div class="actions"><button class="btn" type="button" id="setupBack">Back</button><button class="btn primary" type="button" id="setupNext">Next</button><button id="setupFinish" class="btn primary" type="submit">',1)
    html_page=html_page.replace('</header>','<button type="button" class="btn" id="setupLanguage" aria-label="Change setup language">فارسی / English</button></header>',1)
    html_page=html_page.replace('<div class="steps">','<div class="setup-progress-head"><span id="setupStepTitle"></span><span id="setupPosition" role="status" aria-live="polite"></span></div><progress id="setupProgress" aria-label="Setup progress"></progress><div class="steps">',1)
    css='<style>.step{display:none}.step.current{display:block}</style>'
    script='''<script>
    (()=>{const prefix=PREFIX,csrf=CSRF;let index=START,lang='fa';try{lang=localStorage.getItem('dbot_ui_language')==='en'?'en':'fa'}catch{}let stages=[...document.querySelectorAll('.step')],form=document.querySelector('main form'),error=document.getElementById('setupError');
    function show(preserve){stages=[...document.querySelectorAll('.step')].filter(el=>!el.dataset.feature||(el.dataset.feature==='openvpn'&&document.querySelector('#setupServers [data-provider=mikrotik]'))||document.querySelector('[name=feature_'+el.dataset.feature+']')?.checked);if(preserve)index=stages.indexOf(preserve);index=Math.max(0,Math.min(index,stages.length-1));document.querySelectorAll('.step').forEach(el=>el.classList.remove('current'));const frame=stages[index].querySelector('iframe');if(frame&&!frame.src)frame.src=frame.dataset.src;document.documentElement.dir=lang==='fa'?'rtl':'ltr';document.documentElement.lang=lang;document.querySelectorAll('[data-en]').forEach(el=>el.textContent=el.dataset[lang]);stages.forEach((el,i)=>el.classList.toggle('current',i===index));document.getElementById('setupProgress').max=stages.length;document.getElementById('setupProgress').value=index+1;document.getElementById('setupPosition').textContent=(lang==='fa'?'مرحله ':'Step ')+(index+1)+' / '+stages.length;document.getElementById('setupStepTitle').textContent=stages[index].querySelector('h2')?.textContent||'';document.getElementById('setupLanguage').textContent=lang==='fa'?'English':'فارسی';document.getElementById('setupProgress').setAttribute('aria-label',lang==='fa'?'پیشرفت راه‌اندازی':'Setup progress');document.getElementById('setupBack').hidden=index===0;document.getElementById('setupBack').textContent=lang==='fa'?'قبلی':'Back';document.getElementById('setupNext').hidden=index===stages.length-1;document.getElementById('setupNext').textContent=lang==='fa'?'تأیید و ادامه':'Confirm and continue';document.getElementById('setupFinish').hidden=index!==stages.length-1;document.getElementById('setupFinish').textContent=lang==='fa'?'پایان راه‌اندازی':'Complete setup';}
    const text=(en,fa)=>lang==='fa'?fa:en;
    async function setupRequest(path,data){
      let response;try{response=await fetch(prefix+path,{method:'POST',credentials:'same-origin',redirect:'manual',headers:{Accept:'application/json','X-CSRF-Token':csrf,'X-Requested-With':'fetch'},body:data})}catch{throw Error(text('Connection to the web panel failed. Try again.','ارتباط با وب‌پنل برقرار نشد؛ دوباره تلاش کنید.'))}
      if(response.status===401||response.type==='opaqueredirect'||(response.status>=300&&response.status<400))throw Error(text('Your session expired. Sign in again, then check the server list before retrying.','نشست ورود منقضی شده؛ دوباره وارد شوید و پیش از تلاش مجدد، فهرست سرورها را بررسی کنید.'));
      const contentType=response.headers.get('content-type')||'';
      const result=await response.json().catch(()=>null);
      if(contentType.includes('text/html')||!result||typeof result!=='object'||Array.isArray(result))throw Error(text('The web panel returned a non-JSON page. Check your login, private web path and reverse proxy; the previous action may already have been saved.','وب‌پنل به‌جای JSON صفحه دیگری برگرداند. ورود، مسیر خصوصی وب و پروکسی را بررسی کنید؛ عملیات قبلی ممکن است ذخیره شده باشد.'));
      if(!response.ok||result.ok!==true)throw Error(result.message||(typeof result.detail==='string'?result.detail:text('The request failed. Check the web panel logs.','درخواست انجام نشد؛ لاگ وب‌پنل را بررسی کنید.')));
      return result;
    }
    document.getElementById('setupLanguage').onclick=()=>{lang=lang==='fa'?'en':'fa';try{localStorage.setItem('dbot_ui_language',lang)}catch{}show()};
    document.getElementById('setupBack').onclick=()=>{if(dirty){error.textContent=lang==='fa'?'ابتدا فرم را ذخیره کنید.':'Save the form first.';return;}index--;show()};document.getElementById('setupNext').onclick=async()=>{error.textContent='';if(index===0&&!document.querySelector('#setupServers li')){error.textContent=lang==='fa'?'ابتدا یک سرور را اضافه کنید.':'Add a server first.';return;}for(const field of stages[index].querySelectorAll('input,textarea,select')){if(field.required&&!field.checkValidity()){field.reportValidity();return;}}try{await saveProgress();index++;show()}catch(e){error.textContent=e.message}};
    document.getElementById('setupAddServer').onclick=async()=>{const button=document.getElementById('setupAddServer');button.disabled=true;error.textContent='';const success=document.getElementById('setupServerSuccess');success.hidden=true;success.textContent='';delete success.dataset.en;delete success.dataset.fa;try{const data=new FormData();document.querySelectorAll('[data-server]').forEach(el=>data.set(el.dataset.server,el.value));await setupRequest('/admin/servers/add',data);const li=document.createElement('li');li.dataset.provider=data.get('server_type');li.textContent=data.get('name');document.getElementById('setupServers').append(li);document.querySelectorAll('[data-server][type=password]').forEach(el=>el.value='');success.dataset.en='Your server has been added successfully.';success.dataset.fa='سرور شما با موفقیت اضافه شد.';success.textContent=success.dataset[lang];success.hidden=false}catch(e){error.textContent=e.message}finally{button.disabled=false}};
    let dirty=false;
    window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==stages[index]?.querySelector('iframe')?.contentWindow)return;if(e.data?.type==='dbot-setup-dirty')dirty=true;if(e.data?.type==='dbot-setup-saved'){dirty=false;const active=stages[index];fetch(prefix+'/admin/api/v2/capabilities',{headers:{'X-Requested-With':'fetch'}}).then(r=>r.json()).then(data=>{Object.entries(data.features||{}).forEach(([key,value])=>{const field=document.querySelector('[name=feature_'+key+']');if(field)field.checked=!!value});show(active)}).catch(()=>{})}});
    async function saveProgress(){if(dirty)throw Error(lang==='fa'?'ابتدا تغییرات فرم را ذخیره کنید.':'Save the form changes first.');const data=new FormData();stages[index].querySelectorAll('[name]').forEach(el=>{if((el.type==='radio'||el.type==='checkbox')&&!el.checked)return;data.set(el.name,el.value)});document.querySelectorAll('input[type=checkbox][name^=feature_]').forEach(el=>data.set(el.name,el.checked?'1':'0'));data.set('step',String(index+1));await setupRequest('/setup/progress',data)}
    form.addEventListener('submit' ,e=>{if(dirty){e.preventDefault();error.textContent=lang==='fa'?'ابتدا فرم را ذخیره کنید.':'Save the form first.';return;}if(index!==stages.length-1){e.preventDefault();return;}document.querySelectorAll('input[type=checkbox][name^=feature_]').forEach(el=>{if(!el.checked){const hidden=document.createElement('input');hidden.type='hidden';hidden.name=el.name;hidden.value='0';form.append(hidden)}})});show();})();</script>'''
    script=script.replace('START',str(int(values.get('setup_step','0')))).replace('PREFIX',json.dumps(prefix)).replace('csrf=CSRF','csrf='+json.dumps(csrf))
    # Add bilingual text for all labels/headings inherited from the original form.
    translations={'WIzard Setup D Bot':'WIzard Setup D Bot','1) Required Channel Membership':'عضویت اجباری کانال','2) Usage Rules':'قوانین استفاده','3) Bot and Home Page Information':'اطلاعات ربات و صفحه اصلی','4) Web Path':'مسیر وب','Yes, enable it':'بله، فعال شود','Yes, show rules':'بله، قوانین نمایش داده شود','No':'خیر','Channel address':'آدرس کانال','Rules text':'متن قوانین','Bot name':'نام ربات','Admin / support Telegram username':'نام کاربری مدیر / پشتیبانی','Description':'توضیحات','Home page text':'متن صفحه اصلی','Secure login path':'مسیر خصوصی ورود','Secure and consistent setup':'راه‌اندازی امن و یکپارچه','The login URL will be /WEB-PATH/login.':'آدرس ورود به‌صورت /WEB-PATH/login خواهد بود.','When enabled, the bot must be an administrator of this channel so it can verify user membership.':'برای بررسی عضویت، ربات باید مدیر کانال باشد.','These settings are saved directly to the database and are the same values used by the Telegram bot. Until this wizard is completed, admins are redirected to this page.':'این تنظیمات مستقیماً ذخیره و در ربات تلگرام استفاده می‌شوند. تا پایان راه‌اندازی، مدیر به این صفحه هدایت می‌شود.'}
    translation_script='<script>(()=>{const translations='+json.dumps(translations,ensure_ascii=False)+''';const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{const key=node.textContent.trim();if(translations[key]&&!['SCRIPT','STYLE'].includes(node.parentElement.tagName)){const span=document.createElement('span');span.dataset.en=key;span.dataset.fa=translations[key];span.textContent=key;node.replaceWith(span)}})})();</script>'''
    return html_page.replace('</head>',css+'</head>',1).replace('</body>',translation_script+script+restore_script(prefix,csrf)+'</body>',1)
